import itertools
def comps(di):
    H,W=len(di),len(di[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if di[i][j] and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); c=[]
                while st:
                    y,x=st.pop(); c.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            n=(y+dy,x+dx)
                            if 0<=n[0]<H and 0<=n[1]<W and di[n[0]][n[1]] and n not in seen:
                                seen.add(n); st.append(n)
                out.append(c)
    return out
